export function makeFile(name) {
  const log = [];
  const file = {
    name,
    log,
    isOpen: false,
    open() {
      file.isOpen = true;
      log.push('open');
    },
    close() {
      file.isOpen = false;
      log.push('close');
    },
    read() {
      if (!file.isOpen) throw new Error('read on a closed file');
      log.push('read');
      return `${name} contents`;
    },
  };
  return file;
}
