test('the wrapper names the operation, and keeps the cause', () => {
  const original = new Error('ECONNREFUSED');
  const wrapped = wrapWithContext(original, 'save invoice');
  eq(wrapped.message, 'save invoice failed');
  ok(wrapped.cause === original);
});

test('the original message is never stomped on', () => {
  const wrapped = wrapWithContext(new Error('ECONNREFUSED'), 'save invoice');
  ok(!wrapped.message.includes('ECONNREFUSED'));
  eq(wrapped.cause.message, 'ECONNREFUSED');
});

test('context carries the operation plus the params', () => {
  const wrapped = wrapWithContext(new Error('boom'), 'save invoice', {
    invoiceId: 91,
    attempt: 2,
  });
  eq(wrapped.context, {
    operation: 'save invoice',
    invoiceId: 91,
    attempt: 2,
  });
});

test('secrets are redacted, not logged', () => {
  const wrapped = wrapWithContext(new Error('boom'), 'sign in', {
    email: 'ada@lovelace.dev',
    password: 'hunter2',
    token: 'abc.def.ghi',
  });
  eq(wrapped.context.password, '[redacted]');
  eq(wrapped.context.token, '[redacted]');
  eq(wrapped.context.email, 'ada@lovelace.dev');
});

test('long values are truncated', () => {
  const wrapped = wrapWithContext(new Error('boom'), 'import', {
    body: 'x'.repeat(60),
  });
  eq(wrapped.context.body, `${'x'.repeat(40)}...`);
});

test('undefined params are dropped and objects are flattened', () => {
  const wrapped = wrapWithContext(new Error('boom'), 'import', {
    cursor: undefined,
    user: { id: 1 },
    tags: ['js'],
    dryRun: false,
  });
  eq(wrapped.context, {
    operation: 'import',
    user: '[object]',
    tags: '[object]',
    dryRun: false,
  });
});

test('contextOf walks the whole chain, outermost first', () => {
  const inner = wrapWithContext(new Error('ECONNREFUSED'), 'db write', {
    table: 'invoices',
  });
  const outer = wrapWithContext(inner, 'save invoice', { invoiceId: 91 });
  eq(contextOf(outer), [
    { operation: 'save invoice', invoiceId: 91 },
    { operation: 'db write', table: 'invoices' },
  ]);
});

test('a non-Error original is normalized into one', () => {
  const wrapped = wrapWithContext('just a string', 'save invoice');
  ok(wrapped.cause instanceof Error);
  eq(wrapped.cause.message, 'just a string');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('returns whatever use produced', async () => {
  const log = [];
  const conn = makeConnection(log);
  const rows = await withResource(
    conn.acquire,
    async () => ['a', 'b'],
    conn.release
  );
  eq(rows, ['a', 'b']);
});

test('acquire, then use, then release', async () => {
  const log = [];
  const conn = makeConnection(log);
  await withResource(
    conn.acquire,
    async (handle) => {
      handle.log.push('use');
      return 'ok';
    },
    conn.release
  );
  eq(log, ['acquire', 'use', 'release']);
});

test('release is awaited — it is closed before we return', async () => {
  const log = [];
  const conn = makeConnection(log);
  await withResource(conn.acquire, async () => 'ok', conn.release);
  eq(log, ['acquire', 'release']);
});

test('releases even when use rejects, and the error escapes', async () => {
  const log = [];
  const conn = makeConnection(log);
  const err = await rejectedBy(() =>
    withResource(
      conn.acquire,
      async () => {
        throw new Error('query failed');
      },
      conn.release
    )
  );
  eq(err.message, 'query failed');
  eq(log, ['acquire', 'release']);
});

test('releases when use throws synchronously too', async () => {
  const log = [];
  const conn = makeConnection(log);
  await rejectedBy(() =>
    withResource(
      conn.acquire,
      () => {
        throw new Error('bad SQL');
      },
      conn.release
    )
  );
  eq(log, ['acquire', 'release']);
});

test('does not release when acquire fails', async () => {
  const release = spy(async () => {});
  const err = await rejectedBy(() =>
    withResource(
      async () => {
        throw new Error('pool exhausted');
      },
      async () => 'never',
      release
    )
  );
  eq(err.message, 'pool exhausted');
  eq(release.callCount, 0);
});

test('a release failure on the happy path still escapes', async () => {
  const err = await rejectedBy(() =>
    withResource(
      async () => 'conn',
      async () => 'rows',
      async () => {
        throw new Error('close failed');
      }
    )
  );
  eq(err.message, 'close failed');
});

test('a release failure never masks the use failure', async () => {
  const err = await rejectedBy(() =>
    withResource(
      async () => 'conn',
      async () => {
        throw new Error('query failed');
      },
      async () => {
        throw new Error('close failed');
      }
    )
  );
  eq(err.message, 'query failed');
  eq(err.releaseError.message, 'close failed');
});

