// ──────────────────────────── tests ──────────────────────────────────────

test('passes the arguments through and returns the value', () => {
  const logger = makeLogger();
  const wrapped = safeHandler((a, b) => a + b, { logger });
  eq(wrapped(2, 3), 5);
  eq(logger.error.callCount, 0);
});

test('a throwing handler returns undefined instead of exploding', () => {
  const logger = makeLogger();
  const wrapped = safeHandler(() => {
    throw new Error('boom');
  }, { logger });
  eq(wrapped(), undefined);
});

test('it logs the failure once, with the name and the error', () => {
  const logger = makeLogger();
  function onSave() {
    throw new Error('boom');
  }
  safeHandler(onSave, { logger })();
  eq(logger.error.callCount, 1);
  eq(logger.error.calls[0][0].handler, 'onSave');
  eq(logger.error.calls[0][0].error.message, 'boom');
});

test('an async handler resolves to its value', async () => {
  const logger = makeLogger();
  const wrapped = safeHandler(async (n) => n * 2, { logger });
  eq(await wrapped(21), 42);
  eq(logger.error.callCount, 0);
});

test('a rejected async handler is caught too', async () => {
  const logger = makeLogger();
  const wrapped = safeHandler(async () => {
    throw new Error('network');
  }, { logger });
  eq(await wrapped(), undefined);
  eq(logger.error.callCount, 1);
  eq(logger.error.calls[0][0].error.message, 'network');
});

test('a non-Error throw is normalized before it is logged', () => {
  const logger = makeLogger();
  safeHandler(() => {
    throw 'just a string';
  }, { logger })();
  ok(logger.error.calls[0][0].error instanceof Error);
  eq(logger.error.calls[0][0].error.message, 'just a string');
});

test('one bad handler does not stop the others', () => {
  const logger = makeLogger();
  const seen = [];
  const handlers = [
    () => seen.push('first'),
    () => {
      throw new Error('second is broken');
    },
    () => seen.push('third'),
  ].map((handler) => safeHandler(handler, { logger }));
  for (const handler of handlers) handler({ type: 'save' });
  eq(seen, ['first', 'third']);
  eq(logger.error.callCount, 1);
});

test('an explicit name beats the function name', () => {
  const logger = makeLogger();
  function onSave() {
    throw new Error('boom');
  }
  safeHandler(onSave, { logger, name: 'save button' })();
  eq(logger.error.calls[0][0].handler, 'save button');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('timeouts and rate limits are retryable', () => {
  ok(isRetryable(new TimeoutError('timed out')));
  ok(isRetryable(new RateLimitError('slow down')));
  eq(classify(new TimeoutError('timed out')), 'retryable');
});

test('validation and not-found are user errors, and never retried', () => {
  ok(isUserError(new ValidationError('email must contain @')));
  ok(isUserError(new NotFoundError('user 42 not found')));
  eq(isRetryable(new ValidationError('nope')), false);
  eq(classify(new NotFoundError('gone')), 'user');
});

test('5xx is retryable, a plain 4xx is not', () => {
  eq(classify(httpError(503)), 'retryable');
  eq(classify(httpError(400)), 'user');
  eq(isRetryable(httpError(404)), false);
});

test('429 is the exception — retryable even though it is a 4xx', () => {
  eq(classify(httpError(429)), 'retryable');
  eq(isUserError(httpError(429)), false);
});

test('socket codes are retryable', () => {
  const dropped = Object.assign(new Error('socket hang up'), {
    code: 'ECONNRESET',
  });
  ok(isRetryable(dropped));
  ok(RETRYABLE_CODES.has(dropped.code));
});

test('anything unrecognised is a bug', () => {
  eq(classify(new TypeError('x.map is not a function')), 'bug');
  eq(classify(new Error('boom')), 'bug');
  eq(classify('just a string'), 'bug');
});

test('nothing is ever both retryable and a user error', () => {
  const samples = [
    new TimeoutError('t'),
    new RateLimitError('r'),
    new ValidationError('v'),
    new NotFoundError('n'),
    httpError(429),
    httpError(404),
    httpError(500),
    new TypeError('bug'),
  ];
  for (const error of samples) {
    ok(!(isRetryable(error) && isUserError(error)), error.message);
  }
});

