test('causeChain lists the messages outermost first', () => {
  const outer = wrap(
    wrap(new Error('ECONNREFUSED'), 'db write failed'),
    'saving failed'
  );
  eq(causeChain(outer), [
    'saving failed',
    'db write failed',
    'ECONNREFUSED',
  ]);
});

test('causeChain of a single error is one message', () => {
