  const fn = spy(flakyAsync(99, () => httpError(400), 'never'));
  const err = await rejectedBy(() =>
    retryOn(fn, { attempts: 5, isRetryable: serverIsBusy })
  );
  eq(err.message, 'HTTP 400');
  eq(fn.callCount, 1);
});

