  const onRetry = spy();
  await rejectedBy(() =>
    retryOn(flakyAsync(99, () => httpError(503), 'never'), {
      attempts: 3,
      isRetryable: serverIsBusy,
      onRetry,
    })
  );
  eq(onRetry.callCount, 2);
  eq(onRetry.calls.map((args) => args[1]), [1, 2]);
});

